/* @lc app=leetcode id=2953 lang=kotlin */ class Solution { fun md(f: IntArray, st: IntArray, x: Int, d: Int, k: Int) = f[x].let { old -> f.set(x, old + d).also { st[0] += (if (old + d == k) 1 else 0) - (if (old == k) 1 else 0) }.also { st[1] += (if (old + d > 0) 1 else 0) - (if (old > 0) 1 else 0) } } fun cnt(seg: String, c: Int, k: Int): Int = (c * k).let { L -> if (L > seg.length) 0 else IntArray(26).let { f -> IntArray(2).let { st -> seg.indices.count { i -> md(f, st, seg[i] - 'a', 1, k).let { if (i >= L) md(f, st, seg[i - L] - 'a', -1, k) }.let { i >= L - 1 && st[0] == c && st[1] == c } } } } } fun countCompleteSubstrings(word: String, k: Int): Int = word.indices.runningFold(0) { id, i -> if (i > 0 && Math.abs(word[i] - word[i - 1]) > 2) id + 1 else id }.drop(1).let { ids -> word.indices.groupBy { ids[it] }.values.map { word.substring(it.first(), it.last() + 1) }.sumOf { s -> (1..26).sumOf { c -> cnt(s, c, k) } } } }